<?php $rows=chr_rows($pdo,'time_policies');$edit=isset($_GET['edit'])?chr_record($pdo,'time_policies',(int)$_GET['edit']):null;$v=$edit?array_merge($edit['values'],['title'=>$edit['title']]):['from'=>date('Y-m-d'),'required_hours'=>8,'half_day_hours'=>4,'minimum_hours'=>0,'allowed_minutes'=>0];if($error)$v=array_merge($v,$_POST);if(can($pdo,$user,'time_policies.manage')):?><details class="card core-editor" <?=($edit||!$rows||$error)?'open':''?>><summary><?=$edit?'Edit time policy':'Add time policy'?></summary><form method="post" class="form-grid core-form"><?php ftoken();chr_hidden('action','att_policy');chr_hidden('id',$edit['id']??0);chr_hidden('version',$edit['version']??0);field('title','Policy name',$v,'text',true);field('allowed_minutes','Allowed grace (minutes)',$v,'number',true);chr_checkbox('apply_in','Apply to check-in',!empty($v['apply_in']));chr_checkbox('apply_out','Apply to check-out',!empty($v['apply_out']));chr_select('shift_id','Assigned shift',$v['shift_id']??0,[0=>'None — default policy']+$shiftOptions);chr_checkbox('default','Company default policy',!empty($v['default']));foreach(['minimum_hours'=>'Minimum hours','half_day_hours'=>'Half-day threshold (hours)','required_hours'=>'Full-day threshold (hours)'] as $k=>$label):?><label><?=h($label)?><input type="number" step="0.25" min="0" max="24" name="<?=h($k)?>" value="<?=h($v[$k])?>" required></label><?php endforeach;choose('overtime_rule','Overtime rule',$v,['After required hours','After shift end','After both']);field('from','Effective from',$v,'date',true);field('to','Effective to',$v,'date');chr_checkbox('active','Active',!$edit||$edit['status']==='Active');?><div class="full"><button class="button primary">Save policy</button></div></form></details><?php endif;?>
<section class="card"><h2>Grace time and validation rules</h2><p>A shift-specific policy takes priority over the default. Policies apply when a new attendance record is calculated; stored attendance keeps its original rules. End a started policy before introducing replacement rules.</p><div class="table-scroll"><table class="directory"><thead><tr><th>Name</th><th>Grace</th><th>Check-in / out</th><th>Shift / default</th><th>Min / half / full hours</th><th>Dates</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$d=$r['values'];?><tr><td><?=h($r['title'])?></td><td><?=h($d['allowed_minutes'])?> min</td><td><?=!empty($d['apply_in'])?'Yes':'No'?> / <?=!empty($d['apply_out'])?'Yes':'No'?></td><td><?=h(!empty($d['default'])?'Company default':($shiftOptions[$d['shift_id']]??'Unavailable'))?></td><td><?=h($d['minimum_hours'].' / '.$d['half_day_hours'].' / '.$d['required_hours'])?></td><td><?=h($d['from'])?> → <?=h($d['to']?:'Ongoing')?></td><td><?=h($r['status'])?></td><td><?php if(can($pdo,$user,'time_policies.manage')):?><a class="button" href="?page=time_policies&edit=<?=(int)$r['id']?>">Edit</a><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8">No additional policies. Existing shift rules remain in use.</td></tr><?php endif;?></tbody></table></div></section>
